const fs = require('fs');
const path = $env.N8N_ERROR_LOG_FILE || '/home/node/.n8n-logs/errors.log';
const item = $input.first().json;
const line = JSON.stringify({
  at: new Date().toISOString(),
  workflow: item.workflow?.name || item.workflow?.id || 'unknown',
  executionId: item.execution?.id || null,
  node: item.node?.name || null,
  message: item.execution?.error?.message || item.error?.message || 'Unknown error',
  stack: item.execution?.error?.stack || null,
}) + '\n';
fs.appendFileSync(path, line);
return [{ json: { logged: true, path } }];
